function F.orderPlan(d, room, budget)
    local items, bays = d.Items or {}, d.Bays or {}
    local kinds, nk = {}, 0
    for _, k in ipairs(bays.Kinds or {}) do kinds[k] = true nk += 1 end
    local maxKinds = tonumber(bays.Max) or 3
    local pricing = {}
    for _, p in ipairs(d.Pricing or {}) do
        for _, sz in ipairs(p.Sizes or {}) do pricing[p.Id .. ":" .. sz.Size] = sz.Price end
    end
    local cands = {}
    local mode = val("o_mode", "Best Profit")
    if mode == "Game Pick" and d.Recommended and type(d.Recommended.Lines) == "table" then
        local byId = {}
        for _, it in ipairs(items) do byId[it.Id] = it end
        for i, l in ipairs(d.Recommended.Lines) do
            local it = byId[l.Id]
            if it and it.Unlocked and (it.Qty or 0) > 0 and (it.Wholesale or 0) > 0 then cands[#cands + 1] = { it = it, score = -i, cap = math.min(l.Qty or it.Qty, it.Qty) } end
        end
    else
        local dw = { Low = 0.7, Normal = 1, High = 1.4 }
        for _, it in ipairs(items) do
            if it.Unlocked and (it.Qty or 0) > 0 and (it.Wholesale or 0) > 0 then
                local price = pricing[it.Id] or it.Wholesale * 2.4
                local margin = price - it.Wholesale
                local score = mode == "Cheapest" and -it.Wholesale or margin * (dw[it.Demand] or 1)
                cands[#cands + 1] = { it = it, score = score, cap = it.Qty }
            end
        end
    end
    table.sort(cands, function(a, b) return a.score > b.score end)
    local cart, n, spent = {}, 0, 0
    local ap = F.inf and F.inf.Appeal
    local per = math.max(2, math.ceil(room / math.max(3, tonumber(ap and ap.KindsTarget) or 8)))
    for pass = 1, 2 do
        for _, c in ipairs(cands) do
            if n >= room then break end
            local sp = c.it.Species
            if kinds[sp] or nk < maxKinds then
                local have = cart[c.it.Id] or 0
                local lim = math.min(c.cap, 20) - have
                if pass == 1 then lim = math.min(lim, per) end
                local q = math.min(lim, room - n, math.floor((budget - spent) / c.it.Wholesale))
                if q > 0 then
                    if not kinds[sp] then kinds[sp] = true nk += 1 end
                    cart[c.it.Id] = have + q
                    n += q
                    spent += q * c.it.Wholesale
                end
            end
        end
    end
    return cart, n, spent
end
