            score += dv.Points[t] or 0
            per[id] = (per[id] or 0) + (dv.Points[t] or 0)
        end
    end
    return score, per
end
F.decBad = {}
function F.decorSpot(item, plot, pid)
    local done, out = false, nil
    local co = coroutine.create(function()
        pcall(function()
            local DC = F.dec.DC
            local owned = {}
            for i in string.gmatch(plot:GetAttribute("OwnedZones") or "", "[^,]+") do owned[i] = true end
            local rects = D.PR.OwnedRects(owned, pid)
            local blocks = {}
            for _, e in ipairs(D.PL.Exclusions(pid) or {}) do blocks[#blocks + 1] = e end
            local okH, hq = pcall(D.PL.HQRects, pid)
            if okH and type(hq) == "table" and hq.MinX then blocks[#blocks + 1] = hq end
            for _, e in ipairs(D.PR.DecorRects(pid) or {}) do if e.MinX then blocks[#blocks + 1] = e end end
            local trees = {}
            for _, c in ipairs(plot.Trees:GetChildren()) do local l = D.PL.ToLocal(pid, c:GetPivot().Position) trees[#trees + 1] = l end
            local function inside(x, z)
                for _, r in ipairs(rects) do if x >= r.MinX and x <= r.MaxX and z >= r.MinZ and z <= r.MaxZ then return true end end
                return false
            end
            local function ok(x, z, rot)
                local r = DC.Rect(item, x, z, rot, "M")
                if not (r and inside(r.MinX, r.MinZ) and inside(r.MaxX, r.MinZ) and inside(r.MinX, r.MaxZ) and inside(r.MaxX, r.MaxZ)) then return false end
                for _, e in ipairs(blocks) do
                    if r.MinX < e.MaxX and e.MinX < r.MaxX and r.MinZ < e.MaxZ and e.MinZ < r.MaxZ then return false end
                end
                for _, t in ipairs(trees) do
                    if t.X > r.MinX - 1 and t.X < r.MaxX + 1 and t.Z > r.MinZ - 1 and t.Z < r.MaxZ + 1 then return false end
                end
                local okS, hit = pcall(D.PR.SolidHit, pid, r)
                return okS and not hit
            end
            local checks = 0
            for _, r in ipairs(rects) do
                for x = math.ceil(r.MinX) + 1, math.floor(r.MaxX) - 1 do
                    for z = math.ceil(r.MinZ) + 1, math.floor(r.MaxZ) - 1 do
                        for _, rot in ipairs({ 0, 90 }) do
                            checks += 1
                            if checks % 80 == 0 then task.wait() end
                            if not RUNNING then return end
                            local key = x .. "," .. z .. "," .. rot
                            if not F.decBad[key] and ok(x, z, rot) then out = { x, z, rot, key } return end
                        end
                    end
                end
            end
        end)
        done = true
    end)
    coroutine.resume(co)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 25 do task.wait(0.1) end
    return out
end
function F.decor()
    if not on("f_decor") or os.clock() < F.dec.wait then return false end
    F.dec.wait = os.clock() + 30
    local plot, pid = M.plot()
    if not (plot and D.PR and D.PL and F.decorMods()) then return false end
    local dv = F.dec.CC.DecorVisit
    local target = (dv.BuyerBonus and dv.BuyerBonus.AtScore) or 40
    local score, per = F.decorScore(plot)
    S.decorScore, S.decorTarget = score, target
    if score >= target then F.dec.wait = os.clock() + 120 return false end
    local g = M.inv("Decor", "Get")
    if type(g) ~= "table" then return false end
    local cap = math.max(2, math.floor(target * (dv.CapShare or 0.2)))
    for id, n in pairs(g.Inv or {}) do
        local item = F.dec.DC.Get(id)
        local t = dv.Tiers[id]
        if item and t and not item.Path and n > 0 and (per[id] or 0) < cap then
            local spot = F.decorSpot(item, plot, pid)
            if not spot then F.dec.wait = os.clock() + 90 LOG("decor no space") return false end
            local ok, msg = M.inv("Decor", "Place", id, spot[1], spot[2], spot[3], "M", nil)
            LOG("decor place", id, ok, msg)
            if ok then S.decor = (S.decor or 0) + 1 F.dec.wait = os.clock() + 1 return true end
            F.decBad[spot[4]] = true
            F.dec.wait = os.clock() + 2
            return false
        end
    end
    if g.Crate or (g.Pending or 0) > 0 then return false end
    local budget = F.spendable() * 0.6
    local list = {}
    for _, it in ipairs(F.dec.DC.Items) do
        local t = dv.Tiers[it.Id]
        if t and it.Price and it.Price > 0 and not it.Robux and not it.Premium and not it.Retired and not it.Path and not it.Season then
            list[#list + 1] = { id = it.Id, price = it.Price, pts = dv.Points[t] or 1 }
        end
    end
    table.sort(list, function(a, b) return a.price / a.pts < b.price / b.pts end)
    local cart, need, spent, n = {}, target - score, 0, 0
    for _, c in ipairs(list) do
        local room = math.floor((cap - (per[c.id] or 0)) / c.pts)
        while room > 0 and need > 0 and spent + c.price <= budget do
            cart[c.id] = (cart[c.id] or 0) + 1
            room -= 1 need -= c.pts spent += c.price n += 1
        end
        if need <= 0 then break end
    end
    if n == 0 then return false end
    local ok, msg = M.inv("Decor", "Order", cart)
    LOG("decor order", n, spent, ok, msg)
    if ok then S.decorOrders = (S.decorOrders or 0) + 1 end
    return ok
end
F.orderWait = 0
function F.order()
    if not on("f_order") or os.clock() < F.orderWait then return false end
    F.orderWait = os.clock() + 5
    local plot = M.plot()
    if not plot then return false end
    local lm = F.emp and F.emp.LotManager
    if lm and lm.Hired and lm.On ~= false then return false end
    local st = S.st
    local storage, cap, fly = tonumber(st.Storage) or 0, tonumber(st.StorageCap) or 30, tonumber(st.InFlight) or 0
    local free = (D.PR and D.PL) and F.freeSpots() or cap
    local tr = plot:FindFirstChild("Trees")
    local onLot = tr and #tr:GetChildren() or tonumber(st.Placed) or 0
    local room = math.min(cap - storage - fly, free - storage - fly, F.target() - onLot - storage - fly)
    if room < math.min(4, cap) then return false end
    local budget = M.cash() - M.keep() - F.hqSave()
    if budget < 60 then return false end
    local d = F.supplier(true)
    if type(d) ~= "table" then return false end
    room = math.min(room, (tonumber(d.StorageCap) or cap) - (tonumber(d.StorageUsed) or storage) - (tonumber(d.InFlight) or fly))
    if room < 1 then return false end
    local cart, n, spent = F.orderPlan(d, room, budget)
    if n == 0 then F.orderWait = os.clock() + 20 return false end
    S.task = __T["Ordering trees"] S.taskAt = os.clock()
    local before = os.clock()
    M.fire("OrderTrees", cart)
    local t0 = os.clock()
    repeat task.wait(0.1) until F.ev.orderAt > before or os.clock() - t0 > 4
    if F.ev.orderAt > before and F.ev.orderOk then
        S.orders += 1 S.ordered += n
        LOG("order", n, "for", spent)
        F.orderWait = os.clock() + 3
        return true
    end
    S.orderMsg = F.ev.orderMsg
    LOG("order refused", F.ev.orderMsg)
    F.orderWait = os.clock() + 30
    return false
end
F.priceAt = 0
function F.prices()
    if not on("f_price") or os.clock() - F.priceAt < 20 then return end
    F.priceAt = os.clock()
    local d = F.supplier(false)
    if type(d) ~= "table" then return end
    local pct = (tonumber(val("p_pct", 100)) or 100) / 100
    for _, p in ipairs(d.Pricing or {}) do
        local want = math.clamp(math.floor(p.Suggested * pct + 0.5), p.Min or 1, p.Max or 1e9)
        if p.Price ~= want then M.fire("SetPrice", p.Id, want) LOG("price", p.Id, want) task.wait(0.4) end
    end
end
function F.reserve()
    local d = F.sup.data
    if not on("f_order") or type(d) ~= "table" then return 0 end
    local plot = M.plot()
    local tr = plot and plot:FindFirstChild("Trees")
    if tr and #tr:GetChildren() + (tonumber(S.st.Storage) or 0) >= F.target() * 0.6 then return 0 end
    local w, n = 0, 0
    for _, it in ipairs(d.Items or {}) do if it.Unlocked and it.Size == "M" then w += it.Wholesale or 0 n += 1 end end
    local avg = n > 0 and w / n or 30
    return math.floor(avg * math.min(tonumber(d.StorageCap) or 30, 20))
end
function F.hqSave()
    local nx = F.inf and F.inf.HQ and F.inf.HQ.Next
    if not (on("f_hq") and nx and nx.Cost and type(nx.Checklist) == "table") then return 0 end
    for _, c in ipairs(nx.Checklist) do
