function F.spendable() return M.cash() - M.keep() - F.reserve() - F.hqSave() end
function F.goal()
    local inf = F.inf
    if not (inf and on("f_expand")) then return 0 end
    local best
    for _, sec in ipairs({ inf.Parking, inf.Lot }) do
        local nx = sec and sec.Next
        if nx and nx.Cost and not nx.LockedHQ and (not best or nx.Cost < best) then best = nx.Cost end
    end
    return best or 0
end
function F.build()
    local inf = M.inv("Infrastructure", "Get")
    if type(inf) ~= "table" then return end
    F.inf = inf
    if on("f_hq") and inf.HQ and inf.HQ.Next and inf.HQ.Next.CanBuy and (inf.HQ.Next.Cost or 0) <= M.cash() - M.keep() then
        local ok, msg = M.inv("Infrastructure", "BuyHQ")
        LOG("hq", ok, msg)
        if ok then S.builds += 1 notify(__T["HQ upgraded"]) return end
    end
    if not on("f_expand") then return end
    local opts = {}
    for _, k in ipairs({ "Parking", "Land" }) do
        local sec = inf[k == "Land" and "Lot" or k]
        local nx = sec and sec.Next
        if nx and nx.CanBuy and (nx.Cost or 0) <= F.spendable() then opts[#opts + 1] = { kind = k, cost = nx.Cost } end
    end
    table.sort(opts, function(a, b) return a.cost < b.cost end)
    local o = opts[1]
    if o then
        local ok, msg = M.inv("Infrastructure", "BuyNext", { Kind = o.kind, Id = HttpService:GenerateGUID(false) })
        LOG("expand", o.kind, o.cost, ok, msg)
        if ok then S.builds += 1 end
    end
end
function F.staff()
    if not (on("f_hire") or on("f_staffup") or on("f_break")) then return end
    local e = M.inv("Employees", "Get")
    if type(e) ~= "table" then return end
    F.emp = e
    if on("f_hire") and (e.Hired or 0) < (e.Capacity or 0) then
        local cost = {}
        for _, r in ipairs(e.Roles or {}) do cost[r.Role] = r.Cost end
        local lw = 0
        for _, s in ipairs(e.Staff or {}) do if s.Role == "LotWorker" then lw += 1 end end
        local role
        if (e.Cashiers or 0) < (e.Stations or 1) then role = "Cashier"
        elseif lw < (e.MaxLotWorkers or 0) then role = "LotWorker" end
        if role and (cost[role] or 1e12) <= F.spendable() then
            local ok, msg = M.inv("Employees", "Hire", role)
            LOG("hire", role, ok, msg)
            if ok then S.hires += 1 return end
        end
    end
    if on("f_staffup") then
        local best
        for _, s in ipairs(e.Staff or {}) do
            for _, u in ipairs(s.Upgrades or {}) do
                if (u.Level or 0) < (u.Max or 0) and (u.Cost or 1e12) <= F.spendable() - F.goal() and (not best or u.Cost < best.cost) then best = { id = s.Id, key = u.Key, cost = u.Cost } end
            end
        end
        if best then
            local ok, msg = M.inv("Employees", "Upgrade", { Id = best.id, Key = best.key })
            LOG("staffup", best.key, ok, msg)
            if ok then S.ups += 1 end
        end
    end
end
function F.breaks()
    if not on("f_break") or M.busy or M.playing() or M.carrying() then return end
    local plot = M.plot()
    local rt = plot and plot:FindFirstChild("Runtime")
