function F.rateLoop()
    local hist, last, earned = {}, M.cash(), 0
    while RUNNING do
        local c = M.cash()
        if c > last then earned += c - last end
        last = c
        hist[#hist + 1] = { t = os.clock(), e = earned }
        while #hist > 2 and hist[#hist].t - hist[1].t > 300 do table.remove(hist, 1) end
        local a, b = hist[1], hist[#hist]
        if b.t - a.t > 20 then S.perHour = (b.e - a.e) / (b.t - a.t) * 3600 end
        task.wait(2)
    end
end
