function F.tpTo(name)
    local plot = M.plot()
    if not plot then return end
    local st = plot:FindFirstChild("Static")
    local target
    if name == "Computer" then target = st and st:FindFirstChild("Computer", true)
    elseif name == "Storage" then local f = plot:FindFirstChild("Storage") target = f and f:FindFirstChildWhichIsA("Model")
    elseif name == "Checkout" then target = st and st:FindFirstChild("Register", true)
    else target = st and st:FindFirstChild("GateArch") end
    target = target or plot
    local ok, cf = pcall(function() return target:GetPivot() end)
    if not (ok and cf) then return end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { lp.Character, target }
    for _, off in ipairs({ Vector3.new(5, 0, 5), Vector3.new(-5, 0, 5), Vector3.new(5, 0, -5), Vector3.new(-5, 0, -5), Vector3.new(0, 0, 7) }) do
        local from = cf.Position + off + Vector3.new(0, 3, 0)
        local hit = Workspace:Raycast(from, Vector3.new(0, -20, 0), params)
        if hit and hit.Normal.Y > 0.6 then
            local spot = hit.Position + Vector3.new(0, 3, 0)
            local clear = not Workspace:Raycast(spot, Vector3.new(0, 4, 0), params)
            if clear then M.tp(CFrame.new(spot, Vector3.new(cf.Position.X, spot.Y, cf.Position.Z))) return end
        end
    end
    M.tp(cf.Position + Vector3.new(4, 4, 4))
end
